<script lang="ts">
  import {enhance} from '$app/forms';import type{SubmitFunction}from '@sveltejs/kit';import{toast}from'svelte-sonner';import type{PageProps}from'./$types';import{Badge,Breadcrumb,Button,Card,ConfirmationDialog,Icon,Input,Select,i18n,tienePermiso}from'$lib';let{data}:PageProps=$props();let open=$state(false),processing=$state(false),form:HTMLFormElement,resolveSubmit:(()=>void)|null=null,rejectSubmit:((e:Error)=>void)|null=null;const states=$derived(data.catalogos?.parametros.filter((p:{codigo_grupo:string})=>p.codigo_grupo==='estados_cita')??[]);const canCreate=$derived(tienePermiso(data.usuario.permisos,'operations.appointments.create'));const date=(v:string)=>new Intl.DateTimeFormat(i18n.locale,{dateStyle:'medium',timeStyle:'short',timeZone:data.usuario.preferencias.zona_horaria}).format(new Date(v));const submit:SubmitFunction=()=>{processing=true;return async({result,update})=>{if(result.type==='success'){await update({invalidateAll:true});toast.success(i18n.t('notifications.type.success'),{description:i18n.t('operations.saved')});resolveSubmit?.();}else{const m=result.type==='failure'&&typeof result.data?.operationMessage==='string'?result.data.operationMessage:'operations.saveError';toast.error(i18n.t('notifications.type.error'),{description:i18n.t(m)});rejectSubmit?.(new Error(m));}processing=false;resolveSubmit=null;rejectSubmit=null;};};function confirm(){if(!form.reportValidity())return Promise.reject(new Error('invalid'));return new Promise<void>((r,j)=>{resolveSubmit=r;rejectSubmit=j;form.requestSubmit();});}
</script>
<Breadcrumb items={[{label:i18n.t('nav.dashboard'),href:'/dashboard'},{label:i18n.t('nav.appointments')}]}/><section class="space-y-6"><div class="flex flex-wrap items-end justify-between gap-4"><div><h1 class="text-[28px] font-semibold text-ink">{i18n.t('nav.appointments')}</h1><p class="mt-1.5 text-steel">{i18n.t('operations.appointmentsHelp')}</p></div>{#if canCreate}<Button onclick={()=>open=true}><Icon name="calendar-plus" size={17}/>{i18n.t('operations.newAppointment')}</Button>{/if}</div><Card padding="none">{#if data.citas.length}<div class="divide-y divide-hairline">{#each data.citas as appointment}<article class="grid gap-4 px-5 py-4 sm:grid-cols-[48px_minmax(0,1fr)_auto] sm:items-center"><span class="grid size-11 place-items-center rounded-xl bg-primary-soft text-primary"><Icon name="calendar-days" size={20}/></span><div><strong class="text-sm text-ink">{appointment.motivo}</strong><p class="mt-1 text-xs text-steel">{appointment.mascota?.nombre??'—'} · {appointment.propietario?.nombre_completo??i18n.t('pets.noOwner')}</p></div><div class="sm:text-right"><strong class="block text-sm text-ink">{date(appointment.inicia_en)}</strong><Badge variant="outline-sky">{appointment.estado_cita.etiqueta}</Badge></div></article>{/each}</div>{:else}<div class="grid place-items-center py-14 text-center"><Icon name="calendar-x" size={32} class="text-stone"/><p class="mt-3 text-sm text-steel">{i18n.t('operations.appointmentsEmpty')}</p></div>{/if}</Card></section>
<ConfirmationDialog bind:open size="wide" variant="info" icon="calendar-plus" title={i18n.t('operations.newAppointment')} description={i18n.t('operations.appointmentFormHelp')} confirmLabel={i18n.t('operations.save')} cancelLabel={i18n.t('attentions.cancel')} confirmDisabled={processing} onConfirm={confirm}><form bind:this={form} method="POST" action="?/create" use:enhance={submit} class="grid gap-4 text-left sm:grid-cols-2"><Select name="fid_propietarios" label={i18n.t('owners.title')}><option value="">{i18n.t('pets.noOwner')}</option>{#each data.catalogos?.propietarios??[] as item}<option value={item.id_propietarios}>{item.nombre_completo}</option>{/each}</Select><Select name="fid_mascotas" label={i18n.t('pets.title')}><option value="">—</option>{#each data.catalogos?.mascotas??[] as item}<option value={item.id_mascotas}>{item.nombre}</option>{/each}</Select><Select name="fid_usuarios_responsable" label={i18n.t('operations.responsible')}><option value="">—</option>{#each data.catalogos?.usuarios??[] as item}<option value={item.id_usuarios}>{item.usuario}</option>{/each}</Select><Select name="fid_parametros_estado" label={i18n.t('operations.status')} required><option value="">{i18n.t('forms.select')}</option>{#each states as item}<option value={item.id_parametros}>{item.etiqueta}</option>{/each}</Select><Input name="inicia_en" label={i18n.t('operations.startsAt')} type="datetime-local" required/><Input name="termina_en" label={i18n.t('operations.endsAt')} type="datetime-local" required/><Input name="motivo" label={i18n.t('operations.reason')} required minlength="2" maxlength="250"/><Input name="observaciones" label={i18n.t('operations.observations')} maxlength="500"/></form></ConfirmationDialog>
